package com.madar.files;
import org.junit.Test;
import static org.junit.Assert.*;
public class WatchPlanTest {
 private static long frame(double second){return Math.round(second*44100);}
 private static void commit(PcmRanges ready,WatchWindows w){ready.add(WatchPlan.frame(w.coreStart),WatchPlan.frame(w.coreEnd));}
 @Test public void startingAtFiftyFourProcessesCurrentSceneFirstAndAlsoAllEarlierAudio(){
  for(boolean cloud:new boolean[]{false,true}){PcmRanges ready=new PcmRanges();WatchPlan plan=new WatchPlan(54000000,362000000,cloud,ready);WatchWindows first=plan.next(-1);assertEquals(54000000,first.coreStart);commit(ready,first);assertEquals(0,ready.endFrom(0));WatchWindows history=plan.next(-1);assertEquals(0,history.coreStart);commit(ready,history);int windows=2;WatchWindows next;while((next=plan.next(-1))!=null){assertNotNull(ready.firstGap(WatchPlan.frame(next.coreStart),WatchPlan.frame(next.coreEnd)));commit(ready,next);assertTrue(++windows<30);}assertNull(ready.firstGap(0,frame(362)));assertEquals(frame(362),ready.total());}
 }
 @Test public void backwardRequestHasPriorityWithoutRepeatingTheCurrentScene(){PcmRanges ready=new PcmRanges();WatchPlan plan=new WatchPlan(54000000,360000000,true,ready);commit(ready,plan.next(-1));WatchWindows rewind=plan.next(frame(10));assertEquals(10000000,rewind.coreStart);assertEquals(50000000,rewind.coreEnd);commit(ready,rewind);assertEquals(frame(50),ready.endFrom(frame(10)));assertEquals(frame(94),ready.endFrom(frame(54)));WatchWindows bridge=plan.next(frame(50));assertEquals(50000000,bridge.coreStart);assertEquals(54000000,bridge.coreEnd);commit(ready,bridge);assertEquals(frame(94),ready.endFrom(frame(10)));}
 @Test public void intervalsMergeButSparseFileHolesNeverBecomeReady(){PcmRanges r=new PcmRanges();r.add(54,94);assertEquals(0,r.endFrom(0));assertEquals(53,r.endFrom(53));assertEquals(94,r.endFrom(54));assertArrayEquals(new long[]{0,54},r.firstGap(0,100));r.add(0,40);assertEquals(40,r.endFrom(0));r.add(40,54);assertEquals(94,r.endFrom(0));r.add(10,80);assertEquals(94,r.total());assertArrayEquals(new long[]{94,100},r.firstGap(0,100));}
 @Test public void arbitrarySeekAndRoundTripSampleBoundariesHaveNoGapsOrDuplicateFrames(){for(long origin:new long[]{0,1000,54001000,632500000}){PcmRanges r=new PcmRanges();long end=origin+123456789;WatchPlan p=new WatchPlan(origin,end,true,r);int n=0;WatchWindows w;while((w=p.next(n%3==0?WatchPlan.frame(origin/2):-1))!=null){long a=WatchPlan.frame(w.coreStart),b=WatchPlan.frame(w.coreEnd);assertEquals(a,WatchPlan.frame(WatchPlan.micros(a)));assertEquals(b,WatchPlan.frame(WatchPlan.micros(b)));assertArrayEquals(new long[]{a,b},r.firstGap(a,b));commit(r,w);assertTrue(++n<50);}assertNull(r.firstGap(0,WatchPlan.frame(end)));assertEquals(WatchPlan.frame(end),r.total());}}
 @Test public void shortAudioTailCanFinishWithoutAnInfiniteFinalWindow(){PcmRanges r=new PcmRanges();WatchPlan p=new WatchPlan(54000000,65000000,true,r);WatchWindows w=p.next(-1);r.add(WatchPlan.frame(w.coreStart),frame(64.97));p.trimEnd(frame(64.97));while((w=p.next(-1))!=null)commit(r,w);assertNull(p.next(-1));assertEquals(frame(64.97),r.total());}
}
